sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmTitle ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { dbr:The_First_Day_of_Freedom dbr:Malabimba_–_The_Malicious_Whore }

  # film title (prefer dbp:name, fallback to rdfs:label)
  OPTIONAL { ?film dbp:name ?filmTitle . }
  OPTIONAL { ?film rdfs:label ?filmTitle FILTER (lang(?filmTitle) = "en") }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }

  # director name (prefer rdfs:label)
  OPTIONAL { ?director rdfs:label ?directorName FILTER (lang(?directorName) = "en") }

  # director birth date (prefer dbp:birthDate)
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
}
LIMIT 100

